typedef struct { size_t size; uint32_t magic; } header_t;

void* my_malloc(size_t n) {
    header_t* h = take_chunk(n + sizeof(header_t));  // split a bigger free chunk
    h->size = n;
    h->magic = MAGIC;
    return h + 1;                     // user memory starts after the header
}

void my_free(void* p) {
    header_t* h = (header_t*)p - 1;   // step back to the header
    assert(h->magic == MAGIC);        // catch bad pointers and double frees
    give_back(h, h->size + sizeof(header_t));
    coalesce(h);                      // merge with free neighbours
}
